const baseTimestamp = 1_725_000_000_000;
const projectId = 'legacy';

function criterion(id: string, texto: string, comentario: string, prioridad: 'alta' | 'media' | 'baja', estado: 'pendiente' | 'en-progreso' | 'resuelto' | 'descartado', impacto: 'alto' | 'medio' | 'bajo') {
  return { id, texto, comentario, prioridad, estado, impacto };
}

function prediction(texto: string, umbral: string, conf: 'baja' | 'media' | 'alta') {
  return { texto, umbral, conf };
}

function iteration(id: string, intento: string, resultado: string, ajuste: string, learning: string, evidenceId: string) {
  return {
    id,
    intento,
    resultado,
    ajuste,
    criterioIds: ['criterion-stage-agent-1'],
    methodVersionId: 'method-stage-agent-001',
    objective: 'Validar el canvas principal',
    action: 'Comparar el estado etapa/agente',
    tool: 'Playwright',
    input: 'Fixture stage-agent-workspace',
    result: resultado,
    evidence: [
      { id: evidenceId, kind: 'artifact' as const, label: 'Captura', value: 'IMG-UX-02' },
    ],
    learning,
    nextAdjustment: 'Ajustar tabs y continuidad',
    applicableConditions: ['Desktop 1440 x 900', 'Tablet 1024 x 768'],
    success: true,
    successCriteriaResults: [{ criterion: 'Etapa visible', passed: true }],
    createdAt: baseTimestamp + 10_000,
  };
}

function review(pred: string, observado: string, causa: string, mia: boolean) {
  return { pred, observado, causa, mia };
}

function improvement(criterioId: string, mejora: string, confirmado = true) {
  return { criterioId, mejora, confirmado };
}

function record(
  id: string,
  title: string,
  resourceKind: 'method' | 'tool' | 'learning' | 'automation-candidate',
  sourceTaskId: string | null,
  markdown: string,
  extra: Record<string, unknown> = {},
) {
  return {
    id,
    title,
    resourceKind,
    sourceTaskId: sourceTaskId ?? undefined,
    taskId: sourceTaskId ?? undefined,
    tareaId: sourceTaskId ?? undefined,
    markdown,
    ...extra,
  };
}

function proposal(action: 'accept' | 'edit' | 'reject', proposalId: string, value: unknown = undefined) {
  return {
    action,
    proposalId,
    baseRevision: 'rev-stage-agent-001',
    ...(action === 'edit' ? { value } : {}),
  };
}

